//! The committed fixture files are derived artefacts.
//!
//! `tests/fixtures/*.wasm` is generated by `cargo run --example
//! make_fixtures` from the readable byte-builder in `src/fixtures.rs`. These
//! tests assert that the committed bytes still match, so a reader never has
//! to take an opaque binary on trust, and a change to the builder cannot
//! leave a stale fixture behind.

mod common;
use common::*;

use std::path::PathBuf;

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

#[test]
fn every_committed_fixture_matches_the_builder() {
    for (filename, expected) in all() {
        let path = fixture_dir().join(filename);
        let actual = std::fs::read(&path).unwrap_or_else(|e| {
            panic!(
                "{filename} is missing or unreadable ({e}); regenerate with \
                 `cargo run --example make_fixtures`"
            )
        });
        assert_eq!(
            actual, expected,
            "{filename} is stale; regenerate with `cargo run --example make_fixtures`"
        );
    }
}

#[test]
fn the_fixture_directory_holds_nothing_undocumented() {
    let known: Vec<&str> = all().iter().map(|(n, _)| *n).collect();
    for entry in std::fs::read_dir(fixture_dir()).expect("fixture directory") {
        let entry = entry.expect("directory entry");
        let name = entry.file_name().to_string_lossy().to_string();
        assert!(
            known.contains(&name.as_str()),
            "{name} is in tests/fixtures but is not produced by src/fixtures.rs"
        );
    }
}

#[test]
fn every_fixture_parses_and_audits() {
    for (filename, bytes) in all() {
        let r = wasm_capability_audit::audit_bytes(&bytes, filename)
            .unwrap_or_else(|e| panic!("{filename}: {e}"));
        assert_eq!(r.size_bytes, bytes.len());
        assert_eq!(r.source, filename);
    }
}

#[test]
fn the_fixtures_between_them_exercise_every_severity() {
    use wasm_capability_audit::Severity;
    let mut seen: Vec<Severity> = Vec::new();
    for (_, bytes) in all() {
        let r = wasm_capability_audit::audit_bytes(&bytes, "t").unwrap();
        for f in &r.findings {
            if !seen.contains(&f.severity) {
                seen.push(f.severity);
            }
        }
    }
    for s in Severity::ALL {
        assert!(seen.contains(&s), "no fixture produces a {s} finding");
    }
}

#[test]
fn the_builder_encodes_leb128_the_way_the_parser_decodes_it() {
    // The fixture builder has its own LEB encoder; if the two disagreed the
    // fixtures would be meaningless. Round-trip through a start-section
    // index, which is a bare u32 LEB.
    for value in [0u64, 1, 127, 128, 255, 16384, 1 << 20, u64::from(u32::MAX)] {
        let bytes = module(&[section(8, &uleb(value))]);
        let m = expect_ok(&bytes);
        assert_eq!(m.start, Some(value as u32), "uleb({value})");
    }
    // And the signed encoder, through an i32 constant.
    for value in [0i64, -1, 1, 63, -64, 8192, -8193, i64::from(i32::MIN)] {
        let mut code = vec![0x41];
        code.extend_from_slice(&sleb(value));
        code.push(0x1a);
        expect_ok(&module_with_body(&code));
    }
}
